# Inventors Ladder: The Scientific Revolution (course key invsci). Helpers come from scripts/inventors/build.py.
# Matches the Great Books rungs gb17.galileo-two-new-sciences (1638; Crew and de Salvio 1914), gb17.newton-principia (1687;
# Motte 1729) and gb17.newton-optics (1704; Opticks, 4th ed. 1730). Lives: Galileo 1564–1642, Newton 1642–1727.

LESSONS = {
 "galileo": LES([
  P("Galileo Galilei (1564–1642) was born in Pisa and taught mathematics at the universities of Pisa and Padua. He was a lively writer and a stubborn arguer. Two of his inventions changed science: a telescope good enough to study the sky, and a way of slowing falling motion down so it could be measured."),
  K("Galileo <b>improved on a rumor</b>: he heard of a Dutch spyglass, worked out how it must work, and built better ones. And he <b>slowed falling down</b> with a ball rolling on a gentle ramp, and found that the distance grows with the <b>square of the time</b>."),
  H("The telescope: from a rumor to the moons of Jupiter"),
  P("In 1608 spectacle makers in the Netherlands applied for patents on a tube with two lenses that made distant things look near. Galileo heard about it in 1609. He had never seen one."),
  Q("About ten months ago a report reached my ears that a Dutchman had constructed a telescope, by the aid of which visible objects, although at a great distance from the eye of the observer, were seen distinctly as if near … I prepared a tube, at first of lead, in the ends of which I fitted two glass lenses, both plane on one side, but on the other side one spherically convex, and the other concave.",
    "Galileo", "The Sidereal Messenger (1610)", "Translated by Edward Stafford Carlos (London, 1880)", "https://archive.org/details/thesiderealmesse46036gut", "Shortened."),
  P("His first tube magnified about three times. He ground his own lenses and soon reached about eight, then about twenty times. In January 1610 he turned one on Jupiter and saw four small \"stars\" that moved from night to night, always staying near the planet. They were moons going around Jupiter. He also saw mountains on the Moon, the many stars of the Milky Way, and later the phases of Venus."),
  W("A telescope's magnification is about the focal length of the big front lens divided by the focal length of the eyepiece. Galileo got more magnification by grinding a front lens with a longer focal length and an eyepiece with a shorter one."),
  EX("Magnification", "A front lens has a focal length of 98 cm and the eyepiece 4.9 cm. About how many times does the telescope magnify?",
     ["Magnification $\\approx \\dfrac{98}{4.9}$.", "$98 \\div 4.9 = 20$."], "About 20 times, close to Galileo's best telescopes of 1610."),
  P("Moons circling Jupiter meant not everything goes around the Earth. Galileo argued for Copernicus's idea that the Earth goes around the Sun. That led to his trial by the Roman Inquisition in 1633. He was ordered to abandon the idea and spent his last years confined to his house near Florence."),
  H("The rolling ball: making falling slow enough to measure"),
  P("Aristotle had taught that heavy things fall faster than light ones. Falling is too quick to time with the clocks of Galileo's day. So Galileo rolled a bronze ball down a long, smooth groove tilted gently, which slows the motion while keeping its pattern. He timed it with a water clock: water flowing out of a tank during the roll was weighed."),
  Q("… in such experiments, repeated a full hundred times, we always found that the spaces traversed were to each other as the squares of the times, and this was true for all inclinations of the plane …",
    "Galileo", "Dialogues Concerning Two New Sciences, Third Day (Salviati)", "Translated by Henry Crew and Alfonso de Salvio (Macmillan, 1914)", "https://archive.org/details/dialoguesconcern00gali_0", "A short excerpt."),
  V("iv-incline", None, "Release the ball. Marks appear at equal time steps. The gaps grow 1, 3, 5, 7: the odd numbers. The total distances are 1, 4, 9, 16: the squares."),
  K("Starting from rest, distance is proportional to the square of the time: twice the time, four times the distance. In each equal time step, the ball covers 1, 3, 5, 7, … units, the odd numbers, which add up to the squares."),
  EX("Squares of the times", "A ball rolls 10 cm in the first second. How far has it gone after 3 seconds?",
     ["Distance grows as the square of the time: $3^2 = 9$ times as far.", "$9 \\times 10 = 90$ cm."], "90 cm."),
  LEGEND("<p>The story that Galileo dropped two balls of different weight from the Leaning Tower of Pisa comes from his student Vincenzo Viviani, who wrote it down years later. Galileo's own books do not describe doing it, and many historians doubt it happened as told. What is certain is the inclined plane work he describes, and his clever argument with a heavy and a light stone tied together.</p>"),
  TL([
   ("1564", "Born in Pisa"),
   ("1589", "Teaches mathematics at the University of Pisa"),
   ("1592", "Moves to the University of Padua, where he stays eighteen years"),
   ("1609", "Hears of the Dutch spyglass and builds his own"),
   ("1610", "Sees four moons of Jupiter; publishes The Sidereal Messenger"),
   ("1633", "Tried by the Roman Inquisition; confined to his house"),
   ("1638", "Two New Sciences printed in Leiden, with the inclined plane experiments"),
   ("1642", "Dies at Arcetri, near Florence"),
  ]),
  H("What it led to"),
  P("The telescope opened astronomy, and Galileo's law of falling led straight to Newton. His method, a measured experiment described so others can repeat it, with the results written as mathematics, became the pattern of modern physics."),
  M("Thinking a ball on a ramp moves at a steady speed. It speeds up the whole way down, so it covers more ground in each second than in the one before."),
  GB([("/great-books/the-age-of-reason/galileo-two-new-sciences/", "Galileo: Two New Sciences", "the inclined plane and the tied stones, in Galileo's own words")]),
  TRYIT([("printing-press", "See how printing spread Galileo's books in our printing-press interactive")]),
  P("Read more: " + GK("Galileo_Galilei", "Galileo Galilei") + "."),
  TRY,
 ], "carlos", "crew", "g_galileo"),

 "newton": LES([
  P("Isaac Newton (1642–1727) was born in Woolsthorpe, Lincolnshire, in England, and studied at Trinity College, Cambridge. In 1665–1666, when the university closed because of the plague, he worked at home on mathematics, light and gravity. Later he became Lucasian Professor of Mathematics at Cambridge, President of the Royal Society, and Master of the Royal Mint."),
  K("Newton's inventions came from experiments and from mathematics. He showed with prisms that <b>white light is a mixture of colors</b>; he built the first working <b>reflecting telescope</b> to get around a problem those colors caused; and he showed that <b>one law of gravity</b> explains both a falling apple and the Moon's orbit."),
  H("The prism"),
  P("People had seen prisms make colors for centuries. Most thought the glass somehow added color to white light. Newton tested it. He let a beam of sunlight into a dark room through a small hole and sent it through a prism."),
  Q("In a very dark Chamber, at a round Hole, about one third Part of an Inch broad, made in the Shut of a Window, I placed a Glass Prism, whereby the Beam of the Sun's Light, which came in at that Hole, might be refracted upwards toward the opposite Wall of the Chamber, and there form a colour'd Image of the Sun.",
    "Isaac Newton", "Opticks, Book I, Part I, Proposition II, Experiment 3", "4th edition (London, 1730)", "https://archive.org/details/bim_eighteenth-century_opticks-or-a-treatise-_newton-sir-isaac_1730", "Spelling as printed, with the long s modernized."),
  P("The colored image was long, not round: violet was bent more than red. Then came his key test, the <i>experimentum crucis</i> (\"crucial experiment\"). He picked out one color with a slit and sent it through a second prism. It bent again, but it stayed the same color. The prism wasn't making colors; it was sorting colors that were already in the white light. A lens could put them back together into white."),
  V("iv-prism", None, "Send white light through the prism and see it spread. Then switch on the second prism: a single color bends again but does not split."),
  H("The reflecting telescope"),
  P("Lenses act a little like prisms, so telescopes of the time made colored fringes around bright objects. Newton thought (wrongly, as it later turned out) that this could not be fixed in a lens. So he used a curved mirror instead, which reflects all colors the same way. Around 1668 he built a small reflecting telescope about six inches long, grinding the metal mirror himself. The Royal Society saw a copy in 1671 and elected him a Fellow in 1672. Most large research telescopes today are reflectors."),
  H("Gravity: from the apple to the Moon"),
  P("Galileo had worked out how things fall on Earth. Newton asked whether the same pull reaches the Moon. If the Moon is about 60 times farther from Earth's center than we are, and gravity weakens with the square of the distance, then at the Moon it should be $60^2 = 3600$ times weaker. He checked that this weaker pull is just right to bend the Moon's path into its orbit. In the <i>Principia</i> (1687) he showed with a thought experiment how a cannonball could become a moon."),
  Q("If a leaden ball projected from the top of a mountain by the force of gun-powder with a given velocity, and in a direction parallel to the horizon, is carried in a curve line to the distance of two miles before it falls to the ground; the same, if the resistance of the air was took away, with a double or decuple velocity, would fly twice or ten times as far.",
    "Isaac Newton", "The Mathematical Principles of Natural Philosophy, Definition V", "Translated by Andrew Motte (London, 1729)", "https://archive.org/details/bim_eighteenth-century_principia-english-th_newton-sir-isaac_1729_1", "Spelling as printed, with the long s modernized."),
  V("iv-cannon", None, "Fire the cannon faster and faster. At about 7.9 km/s (with no air) the ball falls around the curve of the Earth and never lands: it is in orbit."),
  EX("Weaker with distance", "Gravity weakens with the square of the distance. How much weaker is it at 4 times the distance from Earth's center?",
     ["$4^2 = 16$.", "So the pull is $\\dfrac{1}{16}$ as strong."], "16 times weaker."),
  P("Newton gave credit to those before him. In a letter to Robert Hooke in February 1676 (1675 by the English calendar of the time) he wrote: \"If I have seen further it is by standing on ye shoulders of Giants.\" (The saying is older than Newton, and the spelling in his letter is \"sholders.\") He and Hooke also argued bitterly, over light and over who first had the idea that gravity weakens with the square of distance."),
  LEGEND("<p>Did an apple fall on Newton's head? No source says so. The apple story comes from Newton himself, late in life: he told his friend William Stukeley that seeing an apple fall in his garden at Woolsthorpe set him thinking about gravity. So the apple falling is Newton's own memory, told decades later; the bump on the head is a cartoon.</p>"),
  TL([
   ("1642", "Born at Woolsthorpe, Lincolnshire, on Christmas Day (Old Style calendar)"),
   ("1661", "Enters Trinity College, Cambridge"),
   ("1665–1666", "Plague closes the university; Newton works at home on light, gravity and calculus"),
   ("c. 1668", "Builds the first working reflecting telescope"),
   ("1672", "Elected to the Royal Society; publishes his theory of light and colors"),
   ("1687", "Principia: the laws of motion and universal gravitation"),
   ("1704", "Opticks: his experiments with light"),
   ("1727", "Dies in London"),
  ]),
  EX("A long wait", "Newton did his first prism experiments around 1666 and published Opticks in 1704. How many years later was that?",
     ["$1704 - 1666 = 38$."], "38 years."),
  H("What it led to"),
  P("Newton's laws explain tides, planets, comets and the paths of spacecraft. His study of light founded the science of the spectrum, which today tells astronomers what stars are made of. And his reflecting telescope is the ancestor of the great mirrors in observatories."),
  M("Thinking the prism adds colors to light. White light already holds all the colors; the prism bends each a little differently, so they spread out."),
  GB([("/great-books/the-age-of-reason/newton-principia/", "Newton: The Principia", "the laws of motion and the cannonball on the mountain"),
      ("/great-books/the-age-of-reason/newton-optics/", "Newton: Optics", "the prism experiments in Newton's own words")]),
  TRYIT([("electromagnet", "Gravity is one force you can't switch off. Build an electromagnet, a force you can")]),
  P("Read more: " + GK("Isaac_Newton", "Isaac Newton") + "."),
  TRY,
 ], "opticks", "motte", "g_newton"),
}
